151: function Complete-ReplBeginTurnAfterPersist {
152:     param(
153:         [bool]$Persisted,
154:         [bool]$Degraded,
155:         [string]$FailsafePath = '',
156:         [string]$CurrentTurnFile = '',
157:         [hashtable]$TurnState = $null
158:     )
159:     if (Test-ReplBeginTurnDegradedQueued -Persisted $Persisted -Degraded $Degraded) {
160:         # FR-MCP-SESSIONLIFE-001: keep the turn file already written. Record degraded
161:         # on that object. Do not replace queryText, planFile, todoId, or audit fields.
162:         # AGENTS.md rule 12 / HV08: mutate via YAML object helpers so paths with
163:         # spaces or '#' survive round-trip (HV04).
164:         if ($CurrentTurnFile) {
165:             if (Test-Path -LiteralPath $CurrentTurnFile) {
166:                 $doc = Read-McpYamlObject -Path $CurrentTurnFile -Create
167:                 if ($doc -isnot [System.Collections.IDictionary]) { $doc = [ordered]@{} }
168:                 $doc['degraded'] = $true
169:                 if (-not [string]::IsNullOrWhiteSpace($FailsafePath)) {
170:                     $doc['failsafePath'] = $FailsafePath
171:                 }
172:                 Write-McpYamlObject -Path $CurrentTurnFile -Document $doc
173:             } elseif ($TurnState) {
174:                 $doc = [ordered]@{
175:                     turnRequestId = $TurnState.turnRequestId
176:                     sessionId = $TurnState.sessionId
177:                     status = 'in_progress'
178:                     degraded = $true
179:                 }
180:                 if (-not [string]::IsNullOrWhiteSpace($FailsafePath)) {
181:                     $doc['failsafePath'] = $FailsafePath
182:                 }
183:                 Write-McpYamlObject -Path $CurrentTurnFile -Document $doc
184:             }
185:         }
186:         return @{ ok = $true; degraded = $true; failsafeRetained = (-not [string]::IsNullOrWhiteSpace($FailsafePath) -and (Test-Path -LiteralPath $FailsafePath)) }
187:     }
188:     if (-not $Persisted) {
189:         return @{ ok = $false; degraded = $false; failsafeRetained = (Test-Path -LiteralPath $FailsafePath) }
190:     }
191:     if ($FailsafePath -and (Test-Path -LiteralPath $FailsafePath)) {
192:         Remove-Item -LiteralPath $FailsafePath -Force -ErrorAction SilentlyContinue
193:     }
194:     return @{ ok = $true; degraded = $false; failsafeRetained = $false }
195: }
