255:     private sealed class ScriptedPool : IIdleSessionPool
256:     {
259:         private const string MainKey = "main";
260: 
263:         private const string SentinelKey = "sentinel";
264: 
267:         private readonly Dictionary<string, (string Key, DateTimeOffset Recorded)> _sessions = new(StringComparer.Ordinal);
268: 
270:         private readonly CleanupClock _cleanupClock;
271: 
273:         private readonly bool _selfScheduling;
274: 
276:         private readonly bool _inclusive;
277: 
279:         private readonly bool _reuse;
280: 
283:         private readonly bool _deferred;
284: 
290:         private readonly bool _awaitingRemovals;
291: 
294:         private readonly bool _reportsAwaitingRemovals;
295: 
298:         private bool _pending;
299: 
302:         private bool _suspended;
303: 
305:         private DateTimeOffset _now;
306: 
308:         private int _created;
309: 
320:         internal ScriptedPool(DateTimeOffset start, CleanupClock cleanupClock, bool selfScheduling, bool inclusive, bool reuse = true, bool deferred = false, bool awaitingRemovals = false, bool reportsAwaitingRemovals = true)
321:         {
322:             _now = start;
323:             _cleanupClock = cleanupClock;
324:             _selfScheduling = selfScheduling;
325:             _inclusive = inclusive;
326:             _reuse = reuse;
327:             _deferred = deferred;
328:             _awaitingRemovals = awaitingRemovals;
329:             _reportsAwaitingRemovals = reportsAwaitingRemovals;
330:         }
331: 
333:         internal enum CleanupClock
334:         {
336:             Scripted,
337: 
339:             Another,
340:         }
341: 
343:         public void SetClock(DateTimeOffset utcNow)
344:         {
345:             _now = utcNow;
346:             if (_selfScheduling)
347:                 TriggerCleanup();
348:         }
349: 
352:         public Task<string> CreateAsync() => Task.FromResult(Create(MainKey));
353: 
356:         public Task<string> CreateSentinelAsync() => Task.FromResult(Create(SentinelKey));
357: 
359:         public Task<bool> ExistsAsync(string sessionId) => Task.FromResult(_sessions.ContainsKey(sessionId));
360: 
363:         public void TriggerCleanup()
364:         {
365:             if (_awaitingRemovals)
366:             {
367:                 if (_suspended)
368:                 {
369:                     _suspended = false;
370:                     RunPass();
371:                 }
372: 
373:                 RunPass();
374:                 return;
375:             }
376: 
377:             if (!_deferred)
378:             {
379:                 RunPass();
380:                 return;
381:             }
382: 
383:             if (_pending)
384:                 RunPass();
385:             _pending = true;
386:         }
387: 
390:         public bool AnyRemovalCanAwait() => _awaitingRemovals && _reportsAwaitingRemovals;
391: 
394:         public bool TriggeredPassFinished() => !_suspended && !_pending;
395: 
397:         public void Dispose()
398:         {
399:         }
400: 
405:         private string Create(string key)
406:         {
407:             if (_reuse)
408:             {
409:                 foreach (var (existing, session) in _sessions)
410:                 {
411:                     if (session.Key != key)
412:                         continue;
413:                     _sessions[existing] = (key, _now);
414:                     return existing;
415:                 }
416:             }
417: 
418:             _created++;
419:             var id = $"session-{_created}";
420:             _sessions[id] = (key, _now);
421:             return id;
422:         }
423: 
429:         private void RunPass()
430:         {
431:             var now = _cleanupClock == CleanupClock.Scripted ? _now : AnotherClock;
432:             foreach (var (id, session) in _sessions.ToArray())
433:             {
434:                 var age = now - session.Recorded;
435:                 if (_inclusive ? age >= IdleTimeout : age > IdleTimeout)
436:                 {
437:                     _sessions.Remove(id);
438:                     if (_awaitingRemovals)
439:                     {
440:                         _suspended = true;
441:                         return;
442:                     }
443:                 }
444:             }
445:         }
446:     }
447: }

