1943:             var timeout = opts.SessionIdleTimeoutMinutes;
1944:             var now = _time.GetUtcNow();
1945:             var staleIds = new List<string>();
1946: 
1947:             foreach (var kvp in _sessions)
1948:             {
1949:                 if (now - kvp.Value.LastUpdatedUtc > timeout && !kvp.Value.IsTurnActive)
1950:                     staleIds.Add(kvp.Key);
