1959:                     sessionId, opts.SessionIdleTimeoutMinutes);
1960: 
1961:                 // Send shutdown command to live Copilot subprocess before terminating
1962:                 if (sessionState.InteractiveSession is { IsAlive: true })
1963:                 {
1964:                     try
1965:                     {
1966:                         var command = opts.IdleShutdownCommand;
1967:                         var sentinel = opts.IdleShutdownSentinel;
1968: 
1969:                         _logger.LogInformation("Idle cleanup: sending shutdown command to {SessionId}", sessionId);
1970:                         var responseStream = sessionState.InteractiveSession.SendStreamingAsync(command, CancellationToken.None);
1971: 
1972:                         await foreach (var line in responseStream)
1973:                         {
1974:                             if (!string.IsNullOrEmpty(line) && line.Contains(sentinel, StringComparison.OrdinalIgnoreCase))
