452:     private readonly record struct PathIdentity(PathRootKind Kind, string Root, string[] Segments)
453:     {
455:         internal StringComparison Comparison => Kind is PathRootKind.Drive or PathRootKind.Unc ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
456: 
462:         internal bool IsWindowsSyntax => Kind is PathRootKind.Drive or PathRootKind.Unc;
