477:             if (path.Length > 2 && IsPathSeparator(path[0]) && IsPathSeparator(path[1]) && !IsPathSeparator(path[2]))
478:             {
479:                 var parts = Split(path[2..]);
480:                 return parts.Length >= 2 ? new PathIdentity(PathRootKind.Unc, parts[0] + "/" + parts[1], parts[2..]) : new PathIdentity(PathRootKind.None, string.Empty, []);
481:             }
482: 
483:             if (path.Length >= 3 && char.IsAsciiLetter(path[0]) && path[1] == ':' && IsPathSeparator(path[2]))
484:                 return new PathIdentity(PathRootKind.Drive, path[..1], Split(path[3..]));
485:             return path.StartsWith('/')
