478:     public async Task<bool> DeleteSessionAsync(string sessionId, CancellationToken cancellationToken = default)
479:     {
480:         EnsureEnabled();
481:         cancellationToken.ThrowIfCancellationRequested();
482:         ArgumentException.ThrowIfNullOrWhiteSpace(sessionId);
483: 
484:         if (!_sessions.TryRemove(sessionId, out var state))
485:             return false;
486: 
487:         lock (state.SyncRoot)
488:         {
489:             try
490:             {
491:                 state.ActiveTurnCts?.Cancel();
492:             }
493:             catch (ObjectDisposedException ex)
494:             {
495:                 _logger.LogError("{ExceptionDetail}", ex.ToString());
496:                 // ignored
497:             }
498: 
499:             state.ActiveTurnCts?.Dispose();
500:         }
501: 
502:         // Gracefully end the interactive Copilot session
503:         if (state.InteractiveSession is not null)
504:         {
505:             if (state.InteractiveSession.IsAlive)
506:             {
507:                 try
508:                 {
509:                     await state.InteractiveSession.EndAsync(TimeSpan.FromSeconds(30)).ConfigureAwait(false);
510:                 }
511:                 catch (Exception ex)
512:                 {
513:                     _logger.LogWarning(ex, "Error ending interactive session: {SessionId}", sessionId);
514:                 }
515:             }
516: 
517:             await state.InteractiveSession.DisposeAsync().ConfigureAwait(false);
518:         }
519: 
520:         state.Gate.Dispose();
521:         return true;
522:     }
