13: public sealed class AgentHealthMonitorService : BackgroundService
14: {
15:     private readonly IAgentProcessManager _agentProcessManager;
16:     private readonly IServiceScopeFactory _scopeFactory;
17:     private readonly ILogger<AgentHealthMonitorService> _logger;
18:     private readonly AgentProcessManagerOptions _options;
19:     private readonly ConcurrentDictionary<string, int> _restartCounts = new(StringComparer.OrdinalIgnoreCase);
20: 
24:     public AgentHealthMonitorService(
25:         IAgentProcessManager agentProcessManager,
26:         IServiceScopeFactory scopeFactory,
27:         IOptions<AgentProcessManagerOptions> options,
28:         ILogger<AgentHealthMonitorService> logger)
29:     {
30:         _agentProcessManager = agentProcessManager;
31:         _scopeFactory = scopeFactory;
32:         _logger = logger;
33:         _options = options.Value;
34:     }
35: 
37:     protected override async Task ExecuteAsync(CancellationToken stoppingToken)
38:     {
39:         var intervalSeconds = Math.Max(5, _options.HealthCheckIntervalSeconds);
40:         while (!stoppingToken.IsCancellationRequested)
41:         {
42:             try
43:             {
44:                 await MonitorOnceAsync(stoppingToken).ConfigureAwait(false);
45:             }
46:             catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
47:             {
48:                 break;
49:             }
50:             catch (Exception ex)
51:             {
52:                 _logger.LogWarning(ex, "Agent health monitor iteration failed.");
53:             }
54: 
55:             await Task.Delay(TimeSpan.FromSeconds(intervalSeconds), stoppingToken).ConfigureAwait(false);
56:         }
57:     }
58: 
59:     private async Task MonitorOnceAsync(CancellationToken cancellationToken)
60:     {
61:         var runningAgents = await _agentProcessManager.ListRunningAsync(null, cancellationToken).ConfigureAwait(false);
62:         await using var scope = _scopeFactory.CreateAsyncScope();
63:         var agentService = scope.ServiceProvider.GetRequiredService<IAgentService>();
64: 
65:         foreach (var info in runningAgents)
66:         {
67:             if (info.Status == Models.AgentProcessStatus.Running || info.Status == Models.AgentProcessStatus.Starting)
68:                 continue;
69: 
70:             var statusKey = BuildKey(info.WorkspacePath, info.AgentId);
71:             if (info.Status == Models.AgentProcessStatus.Stopped && info.ExitCode.GetValueOrDefault() == 0)
72:             {
73:                 _restartCounts.TryRemove(statusKey, out _);
74:                 continue;
75:             }
76: 
77:             var config = await agentService.GetWorkspaceAgentAsync(info.WorkspacePath, info.AgentId, cancellationToken).ConfigureAwait(false);
78:             if (config is null)
79:                 continue;
80: 
81:             var restartPolicy = string.IsNullOrWhiteSpace(config.RestartPolicy) ? "never" : config.RestartPolicy.Trim();
82:             if (string.Equals(restartPolicy, "never", StringComparison.OrdinalIgnoreCase))
83:                 continue;
84: 
85:             if (string.Equals(restartPolicy, "on-failure", StringComparison.OrdinalIgnoreCase) && info.ExitCode.GetValueOrDefault() == 0)
86:                 continue;
87: 
88:             var restartCount = _restartCounts.AddOrUpdate(statusKey, 1, (_, current) => current + 1);
89:             if (restartCount > Math.Max(0, _options.MaxRestarts))
90:             {
91:                 _logger.LogWarning(
92:                     "Skipping restart for agent {AgentId} in {WorkspacePath} because max restarts ({MaxRestarts}) was exceeded.",
93:                     info.AgentId,
94:                     info.WorkspacePath,
95:                     _options.MaxRestarts);
96:                 continue;
97:             }
98: 
99:             var backoffBaseSeconds = Math.Max(0, _options.RestartBackoffBaseSeconds);
100:             var backoffSeconds = backoffBaseSeconds * (int)Math.Pow(2, restartCount - 1);
101:             _logger.LogWarning(
102:                 "Restarting agent {AgentId} in {WorkspacePath} after exit status {Status} and exit code {ExitCode}. Attempt {Attempt}. Backoff {BackoffSeconds}s.",
103:                 info.AgentId,
104:                 info.WorkspacePath,
105:                 info.Status,
106:                 info.ExitCode,
107:                 restartCount,
108:                 backoffSeconds);
109: 
110:             if (backoffSeconds > 0)
111:             {
112:                 await Task.Delay(TimeSpan.FromSeconds(backoffSeconds), cancellationToken).ConfigureAwait(false);
113:             }
114: 
115:             try
116:             {
117:                 await agentService.LaunchAgentAsync(info.WorkspacePath, info.AgentId, cancellationToken).ConfigureAwait(false);
118:             }
119:             catch (Exception ex)
120:             {
121:                 _logger.LogWarning(ex, "Failed to restart agent {AgentId} in {WorkspacePath}.", info.AgentId, info.WorkspacePath);
122:             }
123:         }
124:     }
125: 
126:     private static string BuildKey(string workspacePath, string agentId)
127:         => $"{workspacePath}::{agentId}";
128: }

