101:     internal static (string Row, DateTimeOffset Recorded, bool Selected)[] Rows(AgeDecision decision, DateTimeOffset reference)
102:     {
103:         ArgumentNullException.ThrowIfNull(decision);
104:         return decision.Direction == AgeDirection.Older
105:             ?
106:             [
107:                 ("one step past the threshold", reference - decision.Threshold - Step, true),
108:                 ("exactly at the threshold", reference - decision.Threshold, decision.AtThreshold),
109:                 ("one step short of the threshold", reference - decision.Threshold + Step, false),
110:             ]
111:             :
112:             [
113:                 ("one step short of the threshold", reference + decision.Threshold - Step, false),
114:                 ("exactly at the threshold", reference + decision.Threshold, decision.AtThreshold),
115:                 ("one step past the threshold", reference + decision.Threshold + Step, true),
116:             ];
117:     }
