259:     private static bool ScriptedSelected(AgeDecision decision, DateTimeOffset reference, DateTimeOffset recorded)
260:     {
261:         if (decision.Direction == AgeDirection.Older)
262:         {
263:             var bound = reference - decision.Threshold;
264:             return decision.AtThreshold ? recorded <= bound : recorded < bound;
265:         }
266: 
267:         var upper = reference + decision.Threshold;
268:         return decision.AtThreshold ? recorded >= upper : recorded > upper;
269:     }
