296:     private static IReadOnlyDictionary<string, string> CaptureGuardedFileHashes(string solutionRoot)
297:     {
298:         var hashes = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
299:         foreach (var relativePath in GuardedRepositoryPaths)
300:         {
301:             var path = Path.Combine(solutionRoot, relativePath);
302:             if (File.Exists(path))
303:                 hashes[relativePath] = ComputeHash(path);
304:         }
305: 
306:         return hashes;
307:     }
308: 
309:     private static void VerifyGuardedFilesUnchanged(string solutionRoot, IReadOnlyDictionary<string, string> expectedHashes)
310:     {
311:         foreach (var relativePath in GuardedRepositoryPaths)
312:         {
313:             var path = Path.Combine(solutionRoot, relativePath);
314:             var beforeExists = expectedHashes.TryGetValue(relativePath, out var expectedHash);
315:             if (!beforeExists && File.Exists(path))
316:                 throw new InvalidOperationException($"Integration test modified guarded repository file '{relativePath}'.");
317: 
318:             if (beforeExists && (!File.Exists(path) || !string.Equals(expectedHash, ComputeHash(path), StringComparison.Ordinal)))
319:                 throw new InvalidOperationException($"Integration test modified guarded repository file '{relativePath}'.");
320:         }
321:     }
