323:     private static string ComputeHash(string path)
324:     {
325:         using var stream = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete);
326:         return Convert.ToHexString(SHA256.HashData(stream));
327:     }
