1: <#
2: .SYNOPSIS
3: Reads review records and source history without executing product code.
4: .DESCRIPTION
5: Selects JSON fields, requirement mappings, and commit metadata for independent
6: validation. Only the review command ledger is written.
7: #>
8: [CmdletBinding()]
9: param(
10:     [ValidateSet('Json','Jsonl','RequirementIndex','History','Findings','TaskIds','AbsentCitations')][string]$Mode,
11:     [string]$Path,
12:     [string[]]$Fields = @(),
13:     [string[]]$Ids = @(),
14:     [string]$Range = '3da2db93..0980a52b',
15:     [int]$Start = 0,
16:     [int]$Count = 30
17: )
18: $ErrorActionPreference = 'Stop'
19: $root = '/home/sharpninja/github/McpServer/.worktrees/unit-suite-green-20261019'
20: $receiptRoot = Join-Path $root 'docs/receipts/hv'
21: $exitStatus = 0
22: try {
23:     switch ($Mode) {
24:         'Jsonl' {
25:             foreach ($line in [IO.File]::ReadLines($Path)) {
26:                 $record = $line | ConvertFrom-Json -Depth 100
27:                 if ($Fields.Count -eq 0) { $record.PSObject.Properties | Select-Object Name,@{n='Length';e={([string]$_.Value).Length}} | ConvertTo-Json; continue }
28:                 foreach ($field in $Fields) { if ($record.$field) { $record.$field | ConvertTo-Json -Depth 30 } }
29:             }
30:         }
31:         'AbsentCitations' {
32:             $audit = Get-Content -LiteralPath (Join-Path $receiptRoot 'hv-ug-r14-relaunch-citations.json') -Raw | ConvertFrom-Json -Depth 20
33:             $result = foreach ($group in ($audit.hits | Where-Object { -not $_.present } | Group-Object path)) {
34:                 $lines = [IO.File]::ReadAllLines((Join-Path $root $group.Name))
35:                 [pscustomobject]@{ path=$group.Name; ids=@($group.Group.id | Sort-Object -Unique); historicalLines=@($lines | Where-Object { $_ -match '(?i)historical|fixture data|fixture-only|test data' }) }
36:             }
37:             $result | ConvertTo-Json -Depth 15 | Set-Content -LiteralPath (Join-Path $receiptRoot 'hv-ug-r14-relaunch-citation-labels.json')
38:             $result | ConvertTo-Json -Depth 15
39:         }
40:         'Json' {
41:             $value = Get-Content -LiteralPath $Path -Raw | ConvertFrom-Json -Depth 100
42:             if ($Fields.Count -eq 0) { $value.PSObject.Properties.Name; break }
43:             foreach ($field in $Fields) {
44:                 $selected = $value
45:                 foreach ($part in ($field -split '\.')) { $selected = $selected.$part }
46:                 "FIELD $field"
47:                 @($selected) | Select-Object -Skip $Start -First $Count | ConvertTo-Json -Depth 100
48:             }
49:         }
50:         'RequirementIndex' {
51:             Import-Module powershell-yaml
52:             $effective = (ConvertFrom-Yaml ([IO.File]::ReadAllText((Join-Path $receiptRoot 'hv-ug-r14-relaunch-effective-live.txt')))).payload.result
53:             foreach ($id in $Ids) {
54:                 $records = @(@($effective.functional) + @($effective.technical) + @($effective.testing) | Where-Object id -eq $id)
55:                 $edges = @($effective.mappings | Where-Object { ($_ | ConvertTo-Json -Compress -Depth 20).Contains($id, [StringComparison]::Ordinal) })
56:                 [pscustomobject]@{ id = $id; present = $records.Count -eq 1; title = @($records.title); status = @($records.status); mappings = $edges } | ConvertTo-Json -Depth 30
57:             }
58:         }
59:         'History' {
60:             $commits = @(& git -C $root log --first-parent --format='%H' $Range)
61:             if ($LASTEXITCODE -ne 0) { throw 'git log failed.' }
62:             foreach ($sha in ($commits | Select-Object -Skip $Start -First $Count)) {
63:                 $metadata = @(& git -C $root show -s --format='%H%n%aI%n%cI%n%B' $sha)
64:                 $paths = @(& git -C $root diff-tree --no-commit-id --name-only -r -m --first-parent $sha)
65:                 [pscustomobject]@{ sha = $sha; metadata = $metadata; nonDocsPaths = @($paths | Where-Object { -not $_.StartsWith('docs/') }); pathCount = $paths.Count } | ConvertTo-Json -Depth 10
66:             }
67:         }
68:         'Findings' {
69:             $value = Get-Content -LiteralPath $Path -Raw | ConvertFrom-Json -Depth 100
70:             foreach ($field in @('claims','Claims','claimVerdicts','closure','Closure','failList','unknownList')) {
71:                 if ($value.$field) { "FIELD $field"; @($value.$field) | Select-Object -Skip $Start -First $Count | ConvertTo-Json -Depth 100 }
72:             }
73:         }
74:         'TaskIds' {
75:             $tasks = (Get-Content -LiteralPath (Join-Path $receiptRoot 'hv-ug-r14-relaunch-tasks-check.json') -Raw | ConvertFrom-Json).tasks
76:             $tasks | Select-Object -Skip $Start -First $Count | Select-Object number,explicitIds | ConvertTo-Json -Depth 10
77:         }
78:     }
79: } catch { $exitStatus = 1; Write-Output $_.Exception.ToString() }
80: finally {
81:     [pscustomobject]@{ timestampUtc = [DateTime]::UtcNow.ToString('o'); script = $PSCommandPath; mode = $Mode; path = $Path; fields = $Fields; ids = $Ids; range = $Range; start = $Start; count = $Count; exitCode = $exitStatus } | ConvertTo-Json -Compress | Add-Content -LiteralPath (Join-Path $receiptRoot 'hv-ug-r14-relaunch-command-ledger.jsonl')
82: }
83: exit $exitStatus
