InitialResponseAsync(CancellationToken.None);\n1079\t+            await using IAgentExecutionSession session = await strategy.CreateSessionAsync(CreateRequest(\"cline\"), cancellationToken: TestContext.Current.CancellationToken);\n1080\t+            AgentCliResult result = await session.ReadInitialResponseAsync(CancellationToken.None);\n1081\t \n1082\t-        Assert.Equal(AgentCliResultState.Success, result.State);\n1083\t-        Assert.Equal(\"cline final\", result.Body);\n1084\t-        Assert.NotNull(spawner.StartInfo);\n1085\t-        Assert.Equal(\"cline\", spawner.StartInfo!.FileName);\n1086\t-        Assert.Contains(\"-p\", spawner.StartInfo.ArgumentList);\n1087\t-        Assert.Equal(\"Q:\\\\__mcp_unit_test__\\\\QBrainAi\", GetArgumentAfter(spawner.StartInfo, \"-c\"));\n1088\t-        Assert.Equal(\"xhigh\", GetArgumentAfter(spawner.StartInfo, \"--thinking\"));\n1089\t-        Assert.Contains(\"rendered prompt\", spawner.StartInfo.ArgumentList);\n1090\t-        Assert.Equal(string.Empty, spawner.Process!.StandardInputText);\n1091\t+            Assert.Equal(AgentCliResultState.Success, result.State);\n1092\t+            Assert.Equal(\"cline final\", result.Body);\n1093\t+            Assert.NotNull(spawner.StartInfo);\n1094\t+            Assert.Equal(\"cline\", spawner.StartInfo!.FileName);\n1095\t+            Assert.Contains(\"-p\", spawner.StartInfo.ArgumentList);\n1096\t+            Assert.Equal(\"Q:\\\\__mcp_unit_test__\\\\QBrainAi\", GetArgumentAfter(spawner.StartInfo, \"-c\"));\n1097\t+            Assert.Equal(\"xhigh\", GetArgumentAfter(spawner.StartInfo, \"--thinking\"));\n1098\t+            Assert.Contains(\"rendered prompt\", spawner.StartInfo.ArgumentList);\n1099\t+            Assert.Equal(string.Empty, spawner.Process!.StandardInputText);\n1100\t+        });\n1101\t     }\n1102\t \n1103\t+    /// <summary>The one-shot strategy name is supported and is the default instead of Copilot.</summary>\n1104\t     [Fact]\n1105\t     public void AgentExecutionStrategyNames_SupportsOneShotCliAndDefaultsAwayFromCopilot()\n1106\t     {\n1107\tdiff --git a/tests/QBrainAi.Support.Mcp.Tests/TestSupport/CliTempVariables.cs b/tests/QBrainAi.Support.Mcp.Tests/TestSupport/CliTempVariables.cs\n1108\tnew file mode 100644\n1109\tindex 00000000..e53ac797\n1110\t--- /dev/null\n1111\t+++ b/tests/QBrainAi.Support.Mcp.Tests/TestSupport/CliTempVariables.cs\n1112\t@@ -0,0 +1,129 @@\n1113\t+using Xunit;\n1114\t+\n1115\t+namespace QBrainAi.Support.Mcp.Tests.TestSupport;\n1116\t+\n1117\t+/// <summary>\n1118\t+/// The process-environment variables the CLI strategies read to choose their temporary folder, in each strategy's\n1119\t+/// fallback order: <c>CliBrainSlotChatClient</c> reads MCPSERVER_QUADBRAIN_CLI_TEMP then MCPSERVER_ONESHOT_TEMP;\n1120\t+/// <c>CodexCliAgentExecutionStrategy</c> reads MCPSERVER_CODEX_ONESHOT_TEMP then MCPSERVER_CODEX_TRIAGE_TEMP;\n1121\t+/// <c>OneShotCliAgentExecutionStrategy</c> reads MCPSERVER_ONESHOT_TEMP, MCPSERVER_CODEX_ONESHOT_TEMP, then\n1122\t+/// MCPSERVER_CODEX_TRIAGE_TEMP; <c>GrokCliAgentExecutionStrategy</c> reads MCPSERVER_GROK_ONESHOT_TEMP then\n1123\t+/// MCPSERVER_ONESHOT_TEMP. A test that reaches one of them sets every name of the chain and restores it: the name the\n1124\t+/// strategy under test reads first points at the test folder and every other name at a separate test-owned fallback\n1125\t+/// folder, so an assertion on the test folder proves the primary name won over a set fallback (TR-MCP-USECASE-018\n1126\t+/// AC-006 and TR-MCP-USECASE-019 AC-008 as amended 2026-10-26; operator: \"Strengthen AC, move 14 (Recommended)\" and\n1127\t+/// \"Dependence + proof AC (Recommended)\"; hostile validation finding R6-F1). Shared by the three strategy test classes.\n1128\t+/// </summary>\n1129\t+internal static class CliTempVariables\n1130\t+{\n1131\t+    /// <summary>Every name of the four fallback chains, once each.</summary>\n1132\t+    internal static IReadOnlyList<string> Names { get; } =\n1133\t+    [\n1134\t+        \"MCPSERVER_QUADBRAIN_CLI_TEMP\",\n1135\t+        \"MCPSERVER_ONESHOT_TEMP\",\n1136\t+        \"MCPSERVER_CODEX_ONESHOT_TEMP\",\n1137\t+        \"MCPSERVER_CODEX_TRIAGE_TEMP\",\n1138\t+        \"MCPSERVER_GROK_ONESHOT_TEMP\",\n1139\t+    ];\n1140\t+\n1141\t+    /// <summary>\n1142\t+    /// Runs <paramref name=\"body\"/> with <paramref name=\"primaryName\"/> pointing at a new test folder and every other\n1143\t+    /// name of <see cref=\"Names\"/> at a second new fallback folder, both under the official temporary folder, then\n1144\t+    /// restores every name to its earlier value (an unset name stays unset) and deletes both folders, also when the\n1145\t+    /// body throws. Callers belong to <see cref=\"ProcessEnvironmentCollection\"/>.\n1146\t+    /// </summary>\n1147\t+    /// <param name=\"primaryName\">The name the strategy under test reads first; one of <see cref=\"Names\"/>.</param>\n1148\t+    /// <param name=\"body\">The test body; it receives the test folder.</param>\n1149\t+    /// <returns>A task that completes when the body has run and the variables are restored.</returns>\n1150\t+    internal static Task RunWithTestFolderAsync(string primaryName, Func<string, Task> body)\n1151\t+    {\n1152\t+        ArgumentNullException.ThrowIfNull(body);\n1153\t+        return RunWithTestFoldersAsync(primaryName, (folder, _) => body(folder));\n1154\t+    }\n1155\t+\n1156\t+    /// <summary>\n1157\t+    /// The same as <see cref=\"RunWithTestFolderAsync\"/>, with the body receiving the fallback folder too.\n1158\t+    /// </summary>\n1159\t+    /// <param name=\"primaryName\">The name the strategy under test reads first; one of <see cref=\"Names\"/>.</param>\n1160\t+    /// <param name=\"body\">The test body; it receives the test folder and the fallback folder.</param>\n1161\t+    /// <returns>A task that completes when the body has run and the variables are restored.</returns>\n1162\t+    internal static async Task RunWithTestFoldersAsync(string primaryName, Func<string, string, Task> body)\n1163\t+    {\n1164\t+        ArgumentNullException.ThrowIfNull(body);\n1165\t+        if (!Names.Contains(primaryName, StringComparer.Ordinal))\n1166\t+            throw new ArgumentException($\"{primaryName} is not a CLI temp variable name.\", nameof(primaryName));\n1167\t+\n1168\t+        var previous = Snapshot();\n1169\t+        var stem = Path.Combine(Path.GetTempPath(), \"qbt-cli-temp-\" + Guid.NewGuid().ToString(\"N\"));\n1170\t+        var folder = stem + \"-primary\";\n1171\t+        var fallbackFolder = stem + \"-fallback\";\n1172\t+        Directory.CreateDirectory(folder);\n1173\t+        Directory.CreateDirectory(fallbackFolder);\n1174\t+        try\n1175\t+        {\n1176\t+            foreach (var name in Names)\n1177\t+                Environment.SetEnvironmentVariable(name, name == primaryName ? folder : fallbackFolder);\n1178\t+            await body(folder, fallbackFolder).ConfigureAwait(true);\n1179\t+        }\n1180\t+        finally\n1181\t+        {\n1182\t+            foreach (var (name, value) in previous)\n1183\t+                Environment.SetEnvironmentVariable(name, value);\n1184\t+            foreach (var created in new[] { folder, fallbackFolder })\n1185\t+            {\n1186\t+                try\n1187\t+                {\n1188\t+                    Directory.Delete(created, recursive: true);\n1189\t+                }\n1190\t+                catch (IOException)\n1191\t+                {\n1192\t+                }\n1193\t+            }\n1194\t+        }\n1195\t+    }\n1196\t+\n1197\t+    /// <summary>Reads the current value of every name of <see cref=\"Names\"/> from the process environment.</summary>\n1198\t+    /// <returns>The values by name, null for an unset name.</returns>\n1199\t+    internal static Dictionary<string, string?> Snapshot() =>\n1200\t+        Names.ToDictionary(name => name, name => Environment.GetEnvironmentVariable(name), StringComparer.Ordinal);\n1201\t+\n1202\t+    /// <summary>\n1203\t+    /// Asserts that a snapshot of the variables points the name a strategy reads first, <paramref name=\"primaryName\"/>,\n1204\t+    /// at <paramref name=\"folder\"/> and every other name of <see cref=\"Names\"/> at a different folder,\n1205\t+    /// <paramref name=\"fallbackFolder\"/>, so a test that asserts on <paramref name=\"folder\"/> proves the primary name\n1206\t+    /// won over a set fallback.\n1207\t+    /// </summary>\n1208\t+    /// <param name=\"observed\">The variable values seen, by name.</param>\n1209\t+    /// <param name=\"primaryName\">The name the strategy under test reads first; one of <see cref=\"Names\"/>.</param>\n1210\t+    /// <param name=\"folder\">The folder the primary name must point at.</param>\n1211\t+    /// <param name=\"fallbackFolder\">The folder every other name must point at; not <paramref name=\"folder\"/>.</param>\n1212\t+    internal static void AssertChainAt(IReadOnlyDictionary<string, string?> observed, string primaryName, string folder, string fallbackFolder)\n1213\t+    {\n1214\t+        ArgumentNullException.ThrowIfNull(observed);\n1215\t+        Assert.Contains(primaryName, Names);\n1216\t+        Assert.NotEqual(folder, fallbackFolder);\n1217\t+        foreach (var name in Names)\n1218\t+        {\n1219\t+            Assert.True(observed.TryGetValue(name, out var value), $\"{name} was not observed.\");\n1220\t+            Assert.Equal(name == primaryName ? folder : fallbackFolder, value);\n1221\t+        }\n1222\t+    }\n1223\t+\n1224\t+    /// <summary>\n1225\t+    /// Asserts that every name of <see cref=\"Names\"/> holds the same value after a run as before it, an unset name\n1226\t+    /// included.\n1227\t+    /// </summary>\n1228\t+    /// <param name=\"before\">The values before the run, by name.</param>\n1229\t+    /// <param name=\"after\">The values after the run, by name.</param>\n1230\t+    internal static void AssertRestored(IReadOnlyDictionary<string, string?> before, IReadOnlyDictionary<string, string?> after)\n1231\t+    {\n1232\t+        ArgumentNullException.ThrowIfNull(before);\n1233\t+        ArgumentNullException.ThrowIfNull(after);\n1234\t+        foreach (var name in Names)\n1235\t+        {\n1236\t+            Assert.True(before.TryGetValue(name, out var expected), $\"{name} was not recorded before the run.\");\n1237\t+            Assert.True(after.TryGetValue(name, out var actual), $\"{name} was not recorded after the run.\");\n1238\t+            Assert.Equal(expected, actual);\n1239\t+        }\n1240\t+    }\n1241\t+}\n1242\tdiff --git a/tests/QBrainAi.Support.Mcp.Tests/TestSupport/CliTempVariablesTests.cs b/tests/QBrainAi.Support.Mcp.Tests/TestSupport/CliTempVariablesTests.cs\n1243\tnew file mode 100644\n1244\tindex 00000000..58226294\n1245\t--- /dev/null\n1246\t+++ b/tests/QBrainAi.Support.Mcp.Tests/TestSupport/CliTempVariablesTests.cs\n1247\t@@ -0,0 +1,231 @@\n1248\t+using Xunit;\n1249\t+using static QBrainAi.Support.Mcp.Tests.TestSupport.CliTempVariables;\n1250\t+\n1251\t+namespace QBrainAi.Support.Mcp.Tests.TestSupport;\n1252\t+\n1253\t+/// <summary>\n1254\t+/// Tests the shared CLI temporary-folder variable support of <see cref=\"CliTempVariables\"/>: its name list matches the\n1255\t+/// four strategies' fallback chains, and its snapshot assertions accept a run that pointed the primary name at the test\n1256\t+/// folder, every other name at a separate fallback folder, and restored every name, and reject one that missed or\n1257\t+/// mis-set a name.\n1258\t+/// </summary>\n1259\t+/// <remarks>\n1260\t+/// Requirement coverage: TR-MCP-USECASE-018 AC-006 and TR-MCP-USECASE-019 AC-008 as amended 2026-10-26 (\"set and\n1261\t+/// restore every variable their assertions or the code they call depend on, every name of a fallback chain the code\n1262\t+/// reads\"; operator: \"Strengthen AC, move 14 (Recommended)\" and \"Dependence + proof AC (Recommended)\"; hostile\n1263\t+/// validation finding R6-F1). Test data: scripted snapshots (dictionaries of name to value); these mock gate controls\n1264\t+/// read and write no process environment, so they are unit tests. The class runs in\n1265\t+/// <see cref=\"ProcessEnvironmentCollection\"/> because its binding tests write the process environment; those are\n1266\t+/// integration tests.\n1267\t+/// </remarks>\n1268\t+[Collection(ProcessEnvironmentCollection.Name)]\n1269\t+public sealed class CliTempVariablesTests\n1270\t+{\n1271\t+    private const string Folder = \"/scripted/cli-temp-folder\";\n1272\t+\n1273\t+    private const string Fallback = \"/scripted/cli-temp-fallback\";\n1274\t+\n1275\t+    /// <summary>\n1276\t+    /// The name list holds the five chain names once each: CliBrainSlotChatClient (QUADBRAIN_CLI, ONESHOT), Codex\n1277\t+    /// (CODEX_ONESHOT, CODEX_TRIAGE), one-shot (ONESHOT, CODEX_ONESHOT, CODEX_TRIAGE) and Grok (GROK_ONESHOT, ONESHOT).\n1278\t+    /// </summary>\n1279\t+    [Fact]\n1280\t+    public void Names_HoldEveryChainNameOnce()\n1281\t+    {\n1282\t+        string[] expected =\n1283\t+        [\n1284\t+            \"MCPSERVER_CODEX_ONESHOT_TEMP\",\n1285\t+            \"MCPSERVER_CODEX_TRIAGE_TEMP\",\n1286\t+            \"MCPSERVER_GROK_ONESHOT_TEMP\",\n1287\t+            \"MCPSERVER_ONESHOT_TEMP\",\n1288\t+            \"MCPSERVER_QUADBRAIN_CLI_TEMP\",\n1289\t+        ];\n1290\t+\n1291\t+        Assert.Equal(expected, Names.Order(StringComparer.Ordinal));\n1292\t+    }\n1293\t+\n1294\t+    /// <summary>\n1295\t+    /// Mock gate positive control: a scripted snapshot with the primary name at the folder and every other name at the\n1296\t+    /// fallback folder passes, for each name as the primary.\n1297\t+    /// </summary>\n1298\t+    /// <param name=\"primaryName\">The name read first.</param>\n1299\t+    [Theory]\n1300\t+    [InlineData(\"MCPSERVER_QUADBRAIN_CLI_TEMP\")]\n1301\t+    [InlineData(\"MCPSERVER_ONESHOT_TEMP\")]\n1302\t+    [InlineData(\"MCPSERVER_CODEX_ONESHOT_TEMP\")]\n1303\t+    public void ScriptedChain_PrimaryAtFolderOthersAtFallback_Passes(string primaryName) =>\n1304\t+        AssertChainAt(Scripted(name => name == primaryName ? Folder : Fallback), primaryName, Folder, Fallback);\n1305\t+\n1306\t+    /// <summary>\n1307\t+    /// Mock gate negative controls: the primary name at the fallback folder, another name at the primary folder, a\n1308\t+    /// missing name, an unset name, a fallback folder equal to the primary folder, and a primary name outside the\n1309\t+    /// chain are each rejected, inside a passing harness.\n1310\t+    /// </summary>\n1311\t+    [Fact]\n1312\t+    public void ScriptedChain_WrongSnapshot_IsRejectedInsidePassingHarness()\n1313\t+    {\n1314\t+        const string primary = \"MCPSERVER_QUADBRAIN_CLI_TEMP\";\n1315\t+        var good = Scripted(name => name == primary ? Folder : Fallback);\n1316\t+        var primaryAtFallback = Scripted(_ => Fallback);\n1317\t+        var otherAtFolder = Scripted(name => name == primary || name == \"MCPSERVER_ONESHOT_TEMP\" ? Folder : Fallback);\n1318\t+        var missing = Scripted(name => name == primary ? Folder : Fallback);\n1319\t+        missing.Remove(\"MCPSERVER_GROK_ONESHOT_TEMP\");\n1320\t+        var unset = Scripted(name => name == primary ? Folder : name == \"MCPSERVER_CODEX_TRIAGE_TEMP\" ? null : Fallback);\n1321\t+        var sameFolders = Scripted(_ => Folder);\n1322\t+\n1323\t+        Assert.NotNull(Record.Exception(() => AssertChainAt(primaryAtFallback, primary, Folder, Fallback)));\n1324\t+        Assert.NotNull(Record.Exception(() => AssertChainAt(otherAtFolder, primary, Folder, Fallback)));\n1325\t+        Assert.NotNull(Record.Exception(() => AssertChainAt(missing, primary, Folder, Fallback)));\n1326\t+        Assert.NotNull(Record.Exception(() => AssertChainAt(unset, primary, Folder, Fallback)));\n1327\t+        Assert.NotNull(Record.Exception(() => AssertChainAt(sameFolders, primary, Folder, Folder)));\n1328\t+        Assert.NotNull(Record.Exception(() => AssertChainAt(good, \"MCPSERVER_NOT_A_CHAIN_NAME\", Folder, Fallback)));\n1329\t+    }\n1330\t+\n1331\t+    /// <summary>Mock gate positive control: equal before and after snapshots, an unset name included, pass.</summary>\n1332\t+    [Fact]\n1333\t+    public void ScriptedRestore_EqualSnapshots_Pass() =>\n1334\t+        AssertRestored(Scripted(Prior), Scripted(Prior));\n1335\t+\n1336\t+    /// <summary>\n1337\t+    /// Mock gate negative controls: an after snapshot that left one name at the folder, one that set a previously\n1338\t+    /// unset name, and one missing a name are each rejected, inside a passing harness.\n1339\t+    /// </summary>\n1340\t+    [Fact]\n1341\t+    public void ScriptedRestore_UnrestoredName_IsRejectedInsidePassingHarness()\n1342\t+    {\n1343\t+        var before = Scripted(Prior);\n1344\t+        var leftSet = Scripted(name => name == \"MCPSERVER_QUADBRAIN_CLI_TEMP\" ? Folder : Prior(name));\n1345\t+        var newlySet = Scripted(name => name == \"MCPSERVER_GROK_ONESHOT_TEMP\" ? Folder : Prior(name));\n1346\t+        var missing = Scripted(Prior);\n1347\t+        missing.Remove(\"MCPSERVER_ONESHOT_TEMP\");\n1348\t+\n1349\t+        Assert.NotNull(Record.Exception(() => AssertRestored(before, leftSet)));\n1350\t+        Assert.NotNull(Record.Exception(() => AssertRestored(before, newlySet)));\n1351\t+        Assert.NotNull(Record.Exception(() => AssertRestored(before, missing)));\n1352\t+    }\n1353\t+\n1354\t+    /// <summary>\n1355\t+    /// Binding: for each name as the primary, the helper points that name at a new test folder and every other name at\n1356\t+    /// a separate new fallback folder, both under the official temporary folder, while the body runs, then restores\n1357\t+    /// every scripted earlier value (an unset name included) and deletes both folders. The test writes the process\n1358\t+    /// environment and restores the ambient values, so it is an integration test.\n1359\t+    /// </summary>\n1360\t+    /// <param name=\"primaryName\">The name read first.</param>\n1361\t+    /// <returns>A task that completes when the assertions have run.</returns>\n1362\t+    [Theory]\n1363\t+    [Trait(\"Category\", \"Integration\")]\n1364\t+    [InlineData(\"MCPSERVER_QUADBRAIN_CLI_TEMP\")]\n1365\t+    [InlineData(\"MCPSERVER_ONESHOT_TEMP\")]\n1366\t+    [InlineData(\"MCPSERVER_CODEX_ONESHOT_TEMP\")]\n1367\t+    [InlineData(\"MCPSERVER_CODEX_TRIAGE_TEMP\")]\n1368\t+    [InlineData(\"MCPSERVER_GROK_ONESHOT_TEMP\")]\n1369\t+    public async Task RunWithTestFoldersAsync_PointsPrimaryAndFallbackThenRestoresThem(string primaryName)\n1370\t+    {\n1371\t+        var ambient = Snapshot();\n1372\t+        try\n1373\t+        {\n1374\t+            SetAll(Prior);\n1375\t+            var before = Snapshot();\n1376\t+            string? seenFolder = null;\n1377\t+            string? seenFallback = null;\n1378\t+            Dictionary<string, string?>? inside = null;\n1379\t+            var existed = false;\n1380\t+\n1381\t+            await RunWithTestFoldersAsync(primaryName, (folder, fallbackFolder) =>\n1382\t+            {\n1383\t+                seenFolder = folder;\n1384\t+                seenFallback = fallbackFolder;\n1385\t+                inside = Snapshot();\n1386\t+                existed = Directory.Exists(folder) && Directory.Exists(fallbackFolder);\n1387\t+                return Task.CompletedTask;\n1388\t+            }).ConfigureAwait(true);\n1389\t+\n1390\t+            Assert.NotNull(seenFolder);\n1391\t+            Assert.NotNull(seenFallback);\n1392\t+            Assert.NotNull(inside);\n1393\t+            AssertChainAt(inside, primaryName, seenFolder, seenFallback);\n1394\t+            Assert.True(existed);\n1395\t+            var temp = Path.GetFullPath(Path.GetTempPath());\n1396\t+            Assert.StartsWith(temp, Path.GetFullPath(seenFolder), StringComparison.OrdinalIgnoreCase);\n1397\t+            Assert.StartsWith(temp, Path.GetFullPath(seenFallback), StringComparison.OrdinalI